const query=ref(''); const all=[...p1,...p2,...p3,...p4]; const models=computed(()=>all.filter(x=>x.records.some(r=>r.summary?.trim())).sort((a,b)=>a.model.localeCompare(b.model))); const recordCount=computed(()=>all.reduce((n,x)=>n+x.records.length,0)); const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?models.value.filter(x=>x.model.toLowerCase().includes(q)):models.value})
